if (num_inliers < static_cast<size_t>(options.abs_pose_min_num_inliers)) {
  VLOG(2) << "Absolute pose estimation failed due to insufficient inliers ("
          << num_inliers << " < " << options.abs_pose_min_num_inliers << ")";
  return false;
}

