      args_cstr.reserve(args.size());
      for (const auto& arg : args) {
        args_cstr.push_back(arg.c_str());
      }

      if (RunSurfaceTrimmer(args_cstr.size(),
                            const_cast<char**>(args_cstr.data())) !=
          EXIT_SUCCESS) {
        success = false;
      }
    }

